    const countedDays=dailyTotals.length>1&&dailyTotals.at(-1).total===0?dailyTotals.length-1:dailyTotals.length,currentDaily=dailyTotals.slice(0,countedDays).map(item=>item.total),dailyAverage=currentDaily.length?Math.round(currentDaily.reduce((a,b)=>a+b,0)/currentDaily.length):0,sparkHtml=currentDaily.length>=2?sparkline(currentDaily):'';
