    const dreMetrics=previousDre&&currentDre?[['Faturamento',currentDre.gross_revenue_cents,previousDre.gross_revenue_cents],['Deduções',currentDre.deductions_cents,previousDre.deductions_cents],['Despesas classificadas',Object.values(currentDre.expense_groups||{}).reduce((sum,value)=>sum+BigInt(value||0),0n).toString(),Object.values(previousDre.expense_groups||{}).reduce((sum,value)=>sum+BigInt(value||0),0n).toString()],['Resultado gerencial',currentDre.operating_result_cents,previousDre.operating_result_cents]]:[];
    const dreComparisonCard=preferences['dre-comparison']&&dreMetrics.length?`<section class="card section-card dashboard-chart-card"><div class="section-head"><div><h2>Resultado gerencial · comparativo</h2><p>${dateBR(monthStart)} a ${dateBR(from)} × ${dateBR(previousStart)} a ${dateBR(previousEnd)}.</p></div><button class="text-link" data-page-link="dre">Abrir DRE</button></div><div class="dashboard-dre-metrics">${dreMetrics.map(([label,currentValue,previousValue])=>{const delta=BigInt(currentValue||0)-BigInt(previousValue||0),positiveGood=label==='Faturamento'||label==='Resultado gerencial',tone=delta===0n?'gray':(delta>0n)===positiveGood?'green':'red';return `<article><span>${label}</span><strong>${brl(currentValue)}</strong><small>Anterior: ${brl(previousValue)}</small><em class="${tone}">${delta>0n?'+':''}${brl(delta.toString())}</em></article>`;}).join('')}</div><p class="dashboard-chart-foot">Valores por competência; o CMV depende de regra validada.</p></section>`:'';
