      return `<button type="button" class="dashboard-forecast-metric ${tone}" data-page-link="reports" aria-label="Abrir relatórios para consultar ${label.toLowerCase()}"><span class="dashboard-forecast-label"><i aria-hidden="true">${icon}</i>${label}</span><strong>${brl(value)}</strong><small>Anterior: ${brl(previous)}</small><span class="forecast-compare" role="img" aria-label="Comparação visual entre projeção e mês anterior"><span class="forecast-compare-row"><i style="width:${currentWidth}%"></i></span><span class="forecast-compare-row previous"><i style="width:${previousWidth}%"></i></span><span class="forecast-compare-legend"><span>Projeção</span><span>Mês anterior</span></span></span></button>`;
