    const list=rows.map(r=>{
      const canPay=r.status==='open';
      const action=r.status==='review'?'<button class="button secondary small" data-review-expense="'+esc(r.id)+'">Revisar rascunho</button>':canPay?'<button class="button secondary small" data-action="pay-expense" data-id="'+esc(r.id)+'" data-supplier="'+esc(r.supplier)+'" data-total="'+esc(r.total_cents)+'" data-count="'+esc(r.installment_count)+'">Registrar pagamento</button>':badge(r.derived_status==='Paga'?'Quitada':r.derived_status,r.derived_status==='Paga'?'green':'gray');
      return '<tr'+ctxAttrs('expense',r.id,'Despesa de '+r.supplier)+expenseFilterAttrs(r)+(r.status==='cancelled'?' class="is-deleted"':'')+'><td><strong>'+esc(r.supplier)+'</strong><div class="muted">'+esc(r.document_number||r.description)+'</div>'+(r.attachments||[]).map(a=>'<a class="file-link" target="_blank" rel="noopener noreferrer" href="/api/attachments/'+encodeURIComponent(a.id)+'?unit_id='+encodeURIComponent(state.unit.id)+'">▧ '+esc(a.name)+'</a>').join('<br>')+'</td><td>'+esc(r.category_name||'Sem classificação')+(r.nature?'<div class="muted">'+esc(r.nature)+'</div>':'')+'</td><td>'+dateBR(r.issue_date)+'</td><td>'+dateBR(r.due_date)+'</td><td class="money">'+brl(r.total_cents)+'</td><td class="money">'+brl(outstanding(r).toString())+'</td><td>'+badge(r.derived_status,r.derived_status==='Vencida'?'red':r.derived_status==='Vence em breve'?'amber':r.derived_status==='Paga'?'green':'gray')+'</td><td>'+action+'</td>'+rowMenu()+'</tr>';
    }).join('')+(rows.length?'<tr data-expense-filter-empty hidden><td colspan="9" class="empty-state">Nenhum lançamento corresponde aos filtros.</td></tr>':'')||rowEmpty(9,'Nenhuma despesa cadastrada.');
    const installments=rows.flatMap(expense=>(expense.installments||[]).map(item=>{
      const amount=BigInt(item.amount_cents||0),paid=BigInt(item.paid_cents||0),remaining=amount>paid?amount-paid:0n;
      const due=item.due_date||null,paidOff=remaining===0n||expense.status==='paid',cancelled=expense.status==='cancelled';
      const status=cancelled?'Cancelada':paidOff?'Paga':!due?'Sem vencimento':due<today()?'Vencida':due<=new Date(Date.now()+7*86400000).toISOString().slice(0,10)?'Vence em breve':'Em aberto';
      const tone=status==='Vencida'?'red':status==='Vence em breve'?'amber':status==='Paga'?'green':'gray';
      const action=remaining>0n&&!cancelled&&expense.status==='open'?'<button class="button secondary small" data-action="pay-expense" data-id="'+esc(expense.id)+'" data-supplier="'+esc(expense.supplier)+'" data-total="'+esc(expense.total_cents)+'" data-count="'+esc(expense.installment_count)+'" data-installment="'+esc(item.installment_number)+'">Pagar parcela</button>':'—';
      return {due:due||'9999-12-31',html:'<tr data-status="'+esc(status)+'"'+ctxAttrs('installment',expense.id,'Parcela '+item.installment_number+' · '+expense.supplier)+(cancelled?' class="is-deleted"':'')+'><td>'+dateBR(due)+'</td><td>'+esc(item.installment_number)+'ª de '+esc(expense.installment_count)+'</td><td><strong>'+esc(expense.supplier)+'</strong><div class="muted">'+esc(expense.description)+'</div></td><td>'+esc(expense.category_name||'Sem classificação')+'</td><td class="money">'+brl(amount.toString())+'</td><td class="money">'+brl(paid.toString())+'</td><td class="money">'+brl(remaining.toString())+'</td><td>'+badge(status,tone)+'</td><td>'+action+'</td>'+rowMenu()+'</tr>'};
    })).sort((a,b)=>a.due.localeCompare(b.due));
    const agenda=installments.map(item=>item.html).join('')||rowEmpty(10,'Nenhuma parcela cadastrada.');
    const overdueInstallments=installments.filter(item=>item.html.includes('data-status="Vencida"')).length;
    const soonInstallments=installments.filter(item=>item.html.includes('data-status="Vence em breve"')).length;
    const summary='<div class="mini-kpis due-summary"><div class="mini-kpi">Saldo em aberto <strong>'+brl(openTotal.toString())+'</strong></div><div class="mini-kpi due-alert-red">Parcelas vencidas <strong>'+overdueInstallments+'</strong></div><div class="mini-kpi due-alert-amber">Vencem em até 7 dias <strong>'+soonInstallments+'</strong></div></div>';
    const recurrenceRows=recurrences.map(t=>`<tr><td>${esc(t.supplier)}<div class="muted">${esc(t.description)}</div></td><td>${badge(({monthly:'Mensal',quarterly:'Trimestral',yearly:'Anual'})[t.frequency])}</td><td>${dateBR(t.next_due_on)}</td><td class="money">${brl(t.amount_cents)}</td><td>${can('expenses.pay')?`<button class="button secondary small" data-generate-recurring="${esc(t.id)}">Gerar rascunho</button>`:'—'}</td></tr>`).join('')||rowEmpty(5,'Nenhuma recorrência cadastrada.');
    const recurrenceForm=can('expenses.create')?`<form id="recurrence-form" class="form-grid expense-recurrence-form"><label>Fornecedor<input name="supplier" required></label><label>Descrição<input name="description" required></label><label>Valor esperado (R$)<input name="amount" inputmode="decimal" required></label><label>Frequência<select name="frequency"><option value="monthly">Mensal</option><option value="quarterly">Trimestral</option><option value="yearly">Anual</option></select></label><label>Próximo vencimento<input name="next_due_on" type="date" required></label><label>Categoria<select name="category_id">${selectOptions(categoriesList,'expense')}</select></label><div class="form-actions"><button class="button primary">Cadastrar recorrência</button></div></form>`:'';
