    content().innerHTML=heading('Despesas e notas','Contas a pagar, agenda de parcelas e comprovantes.', '<button class="button primary" data-action="new-expense">＋ Registrar despesa</button>')+summary+recurrenceCard+
      '<section class="card table-card installment-agenda"><div class="table-toolbar"><div><h2>Agenda de parcelas</h2><p>Vencimentos e saldos organizados por data.</p></div><select id="expense-filter" class="period-control"><option value="">Todos os status</option><option>Vencida</option><option>Vence em breve</option><option>Em aberto</option><option>Paga</option><option>Cancelada</option><option>Excluída</option></select></div>'+table(['Vencimento','Parcela','Fornecedor / descrição','Categoria','Valor','Pago','Saldo','Situação','Ação',''],agenda)+'</section>'+
      '<section class="card table-card expense-overview-table"><div class="table-toolbar"><div><h2>Contas e notas</h2><p class="cash-ledger-subtitle">Últimos lançamentos primeiro · <span id="expense-list-count">'+rows.length+' '+(rows.length===1?'lançamento':'lançamentos')+'</span></p></div></div>'+(rows.length?expenseFiltersMarkup(rows):'')+table(['Fornecedor / documento','Categoria / natureza','Emissão','Vencimento','Valor total','Saldo aberto','Status','Ação',''],list)+'</section>';
