    const committedCents=Number(pay.overdue_cents)+Number(pay.due_30_cents),availableCents=Math.max(0,Number(f.available_cents)),usePct=availableCents>0?Math.min(100,Math.round(committedCents/availableCents*100)):(committedCents>0?100:0),coverageTone=usePct>=100?'red':usePct>=70?'amber':'ok';
    const coverage=`<div class="flow-coverage ${coverageTone}"><div class="flow-coverage-head"><span>Compromissos × disponível</span><strong>${usePct}%</strong></div><div class="flow-coverage-track" role="img" aria-label="${usePct}% do disponível comprometido"><span style="width:${usePct}%"></span></div><p>Vencidas e contas dos próximos 30 dias somam ${brl(committedCents)} para ${brl(availableCents)} disponíveis.</p></div>`;
    const payablesCard=`<section class="card cash-action-card"><div class="cash-card-heading"><span class="cash-card-kicker">PROJEÇÃO</span><h2>Contas a pagar</h2><p>Parcelas abertas de despesas confirmadas, comparadas ao total disponível.</p></div><div class="flow-payables"><div class="cash-session-metric"><span>Vencidas</span><strong class="${Number(pay.overdue_cents)>0?'negative':''}">${brl(pay.overdue_cents)}</strong></div><div class="cash-session-metric"><span>Vencem em 7 dias</span><strong>${brl(pay.due_7_cents)}</strong></div><div class="cash-session-metric"><span>Vencem em 30 dias</span><strong>${brl(pay.due_30_cents)}</strong></div></div>${coverage}<div class="cash-close-reference"><span>Disponível após vencidas e 30 dias</span><strong class="${Number(f.projected_cents)<0?'negative':''}">${brl(f.projected_cents)}</strong></div><div class="form-actions"><button class="button secondary" type="button" data-page-link="expenses">Abrir despesas e notas</button></div></section>`;
