    const dayTotals=new Map();for(const m of f.movements){if(!['receipt','payment','fee'].includes(m.kind)||m.reverses_id||m.reversed_at)continue;const item=dayTotals.get(m.occurred_on)||{a:0,b:0};if(m.direction==='in')item.a+=Number(m.amount_cents);else item.b+=Number(m.amount_cents);dayTotals.set(m.occurred_on,item);}
    const flowDays=[...dayTotals.entries()].sort(([a],[b])=>a<b?-1:1).map(([date,v])=>({label:`${date.slice(8)}/${date.slice(5,7)}`,...v}));
