  const dashboardWidgetOptions=[['monthly-sales','Faturamento do mês','Total confirmado no mês atual.'],['sales-target','Meta atingida','Percentual da meta registrada para o dia.'],['cash-balance','Saldo do caixa reservado','Saldo registrado no livro do caixa.'],['open-payables','Contas em aberto','Total restante de despesas em aberto.'],['daily-alerts','Ações do dia e alertas','Vencimentos, caixa e alertas de estoque.'],['daily-checklist','Checklist de abertura e fechamento','Tarefas acompanháveis da operação.'],['today-result','Resultado do mês','Resultado gerencial calculado pela DRE por competência.'],['sales-channels','Faturamento por canal','Compare cada canal com o mesmo trecho do mês anterior.'],['daily-sales','Faturamento diário','Visualize a evolução dos lançamentos ao longo do mês.'],['dre-comparison','Resultado gerencial comparativo','Compare faturamento, despesas e resultado com o mês anterior.'],['expense-groups','Despesas por grupo da DRE','Veja quais grupos concentram os lançamentos do mês.'],['cash-forecast','Previsão de caixa','Entradas, saídas e saldo projetados contra o mês anterior.']];
  const dashboardWidgetDefaultOrder=['monthly-sales','sales-target','cash-balance','open-payables','today-result','daily-sales','sales-channels','daily-alerts','daily-checklist','dre-comparison','expense-groups','cash-forecast'];
  function dashboardPreferenceKey(){return `villa-cruz-dashboard:${state.user?.id||'usuario'}:${state.unit?.id||'unidade'}`;}
  function dashboardWidgetOrder(order){const keys=dashboardWidgetOptions.map(([key])=>key),valid=Array.isArray(order)?order.filter((key,index)=>keys.includes(key)&&order.indexOf(key)===index):[];return [...valid,...dashboardWidgetDefaultOrder.filter(key=>!valid.includes(key))];}
  function mergeDashboardWidgetOrder(currentOrder,visibleOrder){const visible=new Set(visibleOrder);let next=0;return dashboardWidgetOrder(currentOrder).map(key=>visible.has(key)?visibleOrder[next++]:key);}
  function reindexDashboardOrder(list){const items=[...list.querySelectorAll('[data-dashboard-order-item]')];items.forEach((item,index)=>{const position=$('.dashboard-order-position',item);if(position){position.textContent=String(index+1).padStart(2,'0');position.setAttribute('aria-label',`Posição ${index+1}`);}$$('[data-action="dashboard-order-move"]',item).forEach(button=>{const direction=button.dataset.direction;button.disabled=direction==='up'?index===0:index===items.length-1;});});}
  function dashboardPreferences(){const preferences=Object.fromEntries(dashboardWidgetOptions.map(([key])=>[key,true]));let saved={};try{const parsed=JSON.parse(localStorage.getItem(dashboardPreferenceKey())||'{}');if(parsed&&typeof parsed==='object'&&!Array.isArray(parsed))saved=parsed;for(const [key] of dashboardWidgetOptions)if(typeof saved[key]==='boolean')preferences[key]=saved[key];}catch{}preferences.order=dashboardWidgetOrder(saved.order);return preferences;}
