  const traceLabels={name:'Nome',sku:'SKU',barcode:'Código de barras',brand:'Marca',storage_location:'Local',storage_conditions:'Conservação',base_unit:'Unidade-base',purchase_unit:'Unidade de compra',purchase_to_base_quantity:'Conversão',minimum_quantity:'Mínimo',target_quantity:'Estoque desejado',supplier_lead_days:'Prazo de entrega',description:'Descrição',source_document:'Documento',counterparty:'Origem/destinatário',amount_cents:'Valor líquido (centavos)',gross_amount_cents:'Valor bruto (centavos)',fee_cents:'Taxa (centavos)',fee_percent:'Taxa %',category:'Categoria',responsible:'Responsável informado',notes:'Observações',payment_method:'Meio de pagamento',occurred_at:'Data do movimento',affects_drawer:'Afeta gaveta',deleted_at:'Excluído em',item_type:'Tipo de item',expiry_alert_days:'Alerta de validade'};
  const traceTypes={inbound:'Recebimento',outbound:'Saída',adjustment:'Ajuste',waste:'Perda',courtesy:'Cortesia',consumption:'Consumo',reversal:'Estorno'};
  function traceChanges(changes,limit){
    const actions={create:'Cadastro',update:'Alteração',delete:'Exclusão',restore:'Restauração'};
    const rows=changes.map(c=>{const before=c.before_data||{},after=c.after_data||{};const fields=Object.keys(traceLabels).filter(k=>Object.hasOwn(after,k)&&JSON.stringify(before[k]??null)!==JSON.stringify(after[k]??null));return `<tr><td>${new Date(c.created_at).toLocaleString('pt-BR')}</td><td>${esc(c.operator_name||'Não identificado')}</td><td>${esc(actions[c.action]||c.action)}</td><td>${fields.map(k=>`<div><strong>${esc(traceLabels[k])}:</strong> ${esc(before[k]??'Não informado')} → ${esc(after[k]??'Não informado')}</div>`).join('')||'Sem alteração de campos exibidos'}${c.reason?`<p>Motivo: ${esc(c.reason)}</p>`:''}</td></tr>`;}).join('');
    return `<h3>Histórico de alterações</h3><p class="help-text">Até ${limit} eventos mais recentes. Operador identificado pela sessão autenticada.</p>${table(['Registrado em','Operador','Ação','Alterações'],rows||rowEmpty(4,'Nenhuma alteração registrada.'))}`;
  }
  async function showProductHistory(id,page=0){
    const d=await api(`/api/products/${encodeURIComponent(id)}/history?unit_id=${state.unit.id}&page=${page}`),p=d.product;
    const rows=d.movements.map(m=>`<tr><td>${new Date(m.created_at).toLocaleString('pt-BR')}</td><td>${esc(traceTypes[m.movement_type]||m.movement_type)}<div>${m.balance_delta==null?'Sentido não registrado (legado)':`${Number(m.balance_delta)>0?'+':''}${esc(m.balance_delta)} ${esc(p.base_unit)}`}</div></td><td>${esc(m.lot_code||m.lot_id||'Não informado')}<div class="muted">Validade: ${dateBR(m.expires_on)}</div></td><td>${esc(m.supplier||'Não informado')}<div>${esc(m.reference||m.source_document||'Sem documento')}</div></td><td>${esc(m.reason||'Não informado')}</td><td>${esc(m.operator_name||'Não identificado')}<div class="muted">${esc(m.id)}</div></td></tr>`).join('');
    openModal(`Rastreabilidade · ${esc(p.name)}`,`<div class="trace-details"><p><strong>SKU:</strong> ${esc(p.sku||'Não informado')} · <strong>Código de barras:</strong> ${esc(p.barcode||'Não informado')}</p><p><strong>Marca:</strong> ${esc(p.brand||'Não informada')} · <strong>Local:</strong> ${esc(p.storage_location||'Não informado')}</p><p><strong>Conservação:</strong> ${esc(p.storage_conditions||'Não informada')}</p><p>Cadastrado por ${esc(p.created_by_name||'Não identificado')}. Quantidades em ${esc(p.base_unit)}.</p></div><h3>Recebimentos e movimentações</h3>${table(['Registrado em','Tipo / variação','Lote','Origem / documento','Motivo','Operador / registro'],rows||rowEmpty(6,'Sem movimentações.'))}<div class="trace-pagination"><button type="button" class="button secondary" data-trace-prev ${page?'':'disabled'}>Anterior</button><span>Página ${page+1}</span><button type="button" class="button secondary" data-trace-next ${d.has_more?'':'disabled'}>Próxima</button></div>${traceChanges(d.changes,d.changes_limit)}`,{className:'trace-modal'});
    const modal=$$('.modal').at(-1);$('[data-trace-prev]',modal).addEventListener('click',()=>{closeModal(modal);showProductHistory(id,page-1).catch(e=>toast(e.message,true));});$('[data-trace-next]',modal).addEventListener('click',()=>{closeModal(modal);showProductHistory(id,page+1).catch(e=>toast(e.message,true));});
  }
  async function showCashHistory(id){
    const d=await api(`/api/cash/movements/${encodeURIComponent(id)}/history?unit_id=${state.unit.id}`),m=d.movement;
    openModal('Rastreabilidade do caixa',`<div class="trace-details"><p><strong>Registro:</strong> ${esc(m.id)}</p><p><strong>Operador autenticado:</strong> ${esc(m.operator_name||'Não identificado')} · <strong>Responsável informado:</strong> ${esc(m.responsible||'Não informado')}</p><p><strong>Turno:</strong> ${esc(m.shift_name||'Sem turno vinculado')} · ${m.closed_at?'Fechado':'Sem fechamento registrado'}</p><p><strong>Origem / destinatário:</strong> ${esc(m.counterparty||'Não informado')} · <strong>Documento:</strong> ${esc(m.source_document||'Não informado')}</p><p><strong>Valor:</strong> ${brl(m.amount_cents)} · ${m.affects_drawer===false?'Não afeta gaveta':'Afeta gaveta'}</p><p>${esc(m.description)} · ${esc(m.notes||'')}</p></div>${traceChanges(d.changes,d.changes_limit)}`,{className:'trace-modal'});
  }
  async function renderReconciliation(){
    const d=await api('/api/reconciliation?unit_id='+state.unit.id),q=d.quality;
    const rows=d.checks.map(r=>{const changed=String(r.ledger_cents)!==String(r.current_ledger_cents);return `<tr><td>${dateBR(r.as_of)}</td><td>${esc(r.account_name)}</td><td>${brl(r.observed_cents)}</td><td>${brl(r.ledger_cents)}</td><td>${brl(r.difference_cents)} ${changed?badge('Saldo mudou: conferir novamente','amber'):badge(Number(r.difference_cents)===0?'Conferido':'Divergente',Number(r.difference_cents)===0?'green':'amber')}</td><td>${esc(r.source_document)}<div class="muted">${esc(r.notes||'')}</div></td><td>${esc(r.operator_name)}<div class="muted">${new Date(r.created_at).toLocaleString('pt-BR')}</div></td></tr>`;}).join('');
    content().innerHTML=heading('Conferência','Compare o extrato com o registro gerencial e acompanhe pendências.',can('reconciliation.manage')?'<button class="button primary" id="new-reconciliation">Conferir saldo bancário</button>':'')+`<div class="alert-panel amber">A conferência registra uma comparação de saldos, sem importar transações nem ajustar valores. DRE e CMV continuam sujeitos à validação das regras e dos documentos.</div><section class="card section-card"><h2>Pendências para revisão</h2><p class="help-text">Contagens de todo o histórico da unidade; uma ausência de informação não prova erro.</p><div class="mini-kpis"><div class="mini-kpi">Caixas com diferença <strong>${q.cash_differences}</strong></div><div class="mini-kpi">Lotes sem lote, fornecedor ou documento <strong>${q.incomplete_lots}</strong></div><div class="mini-kpi">Movimentos sem sentido registrado <strong>${q.unknown_stock_direction}</strong></div><div class="mini-kpi">Despesas sem grupo DRE <strong>${q.unclassified_expenses}</strong></div></div></section><section class="card table-card trace-report"><div class="table-toolbar"><h2>Conferências registradas</h2><span class="badge gray">Últimas ${d.limit}</span></div>${table(['Data do saldo','Conta','Extrato','Sistema na conferência','Diferença / situação','Documento / observação','Conferido por'],rows||rowEmpty(7,'Nenhuma conferência registrada.'))}</section>`;
    $('#new-reconciliation')?.addEventListener('click',()=>{openModal('Conferir saldo bancário',`<form id="reconciliation-form" class="form-grid trace-form"><label class="form-span-2">Conta<select name="account_id" required><option value="">Selecione</option>${d.accounts.map(a=>`<option value="${esc(a.id)}">${esc(a.name)}${a.active?'':' (inativa)'}</option>`).join('')}</select></label><label>Data do saldo<input type="date" name="as_of" max="${today()}" value="${today()}" required></label><label>Saldo final do extrato (R$)<input name="observed_balance" inputmode="decimal" required placeholder="0,00"></label><label class="form-span-2">Documento de conferência<input name="source_document" maxlength="120" required placeholder="Ex.: extrato da conta, página e data"></label><label class="form-span-2">Observação / explicação da diferença<textarea name="notes" maxlength="1000" rows="3"></textarea><span class="hint">Obrigatória quando existir diferença. O saldo não será alterado.</span></label><div class="form-actions"><button class="button primary">Registrar conferência</button></div></form>`,{className:'entry-modal'});});
  }
  const defaultExpiryOptions=[[0,'Não alertar'],[3,'3 dias antes'],[7,'7 dias antes'],[15,'15 dias antes'],[30,'30 dias antes']];
  const productSelect=(label,name,options,value,action)=>`<label>${label}${action?`<div class="select-add"><select name="${name}">${options}</select><button type="button" class="icon-button" data-action="${action}" aria-label="Adicionar opção">＋</button></div>`:`<select name="${name}">${options}</select>`}</label>`;
  async function productModalData(productId){const [products,cats,suppliers,custom]=await Promise.all([productId?api(`/api/products?unit_id=${state.unit.id}`):Promise.resolve([]),categories(),api(`/api/suppliers?unit_id=${state.unit.id}`),api(`/api/catalog/options?unit_id=${state.unit.id}`)]);return {product:productId?products.find(p=>p.id===productId):null,categories:cats.filter(c=>c.kind==='stock'),suppliers,custom};}
  function productFormMarkup({product:p,categories:cats,suppliers,custom}){const base=baseUnitOptions.map(([v,l])=>`<option value="${esc(v)}" ${p?.base_unit===v?'selected':''}>${l}</option>`).join(''),purchase=purchaseUnitOptions.map(v=>`<option value="${esc(v)}" ${p?.purchase_unit===v?'selected':''}>${esc(v.charAt(0).toUpperCase()+v.slice(1))}</option>`).join(''),types=[...defaultItemTypes.map(label=>({value:label,label})),...custom.filter(x=>x.kind==='item_type').map(x=>({value:x.label,label:x.label}))],typeOptions=types.map(x=>`<option value="${esc(x.value)}" ${(p?.item_type||'Ingrediente')===x.value?'selected':''}>${esc(x.label)}</option>`).join(''),expiry=[...defaultExpiryOptions,...custom.filter(x=>x.kind==='expiry_alert').map(x=>[Number(x.value),`${x.label} antes`])],expiryOptions=expiry.map(([v,l])=>`<option value="${v}" ${Number(p?.expiry_alert_days??7)===Number(v)?'selected':''}>${esc(l)}</option>`).join(''),categoryOptions='<option value="">Sem categoria</option>'+cats.map(c=>`<option value="${esc(c.id)}" ${p?.category_id===c.id?'selected':''}>${esc(c.name)}</option>`).join(''),supplierOptions='<option value="">Sem fornecedor principal</option>'+suppliers.map(s=>`<option value="${esc(s.id)}" ${p?.supplier_id===s.id?'selected':''}>${esc(s.name)}</option>`).join('');return `<form id="product-form" data-product-id="${esc(p?.id||'')}" data-guard-dirty="true" class="form-grid trace-form"><div class="form-section-title">Identificação</div><label class="form-span-2">Nome do produto<input name="name" maxlength="160" value="${esc(p?.name||'')}" required></label><label>SKU/código<input name="sku" maxlength="80" value="${esc(p?.sku||'')}"></label><label>Código de barras<input name="barcode" maxlength="64" value="${esc(p?.barcode||'')}" placeholder="Identificador da embalagem"></label><label>Marca / fabricante<input name="brand" maxlength="120" value="${esc(p?.brand||'')}"></label>${productSelect('Tipo de item','item_type',typeOptions,p?.item_type||'Ingrediente','add-item-type')}${productSelect('Categoria','category_id',categoryOptions,p?.category_id,'add-stock-category')}<div class="form-section-title">Compra e controle de estoque</div>${productSelect('Unidade-base','base_unit',base,p?.base_unit||'unidade','')}${productSelect('Unidade de compra','purchase_unit',purchase,p?.purchase_unit||'unidade','')}<label>Conversão para unidade-base<input name="purchase_to_base_quantity" type="number" min="0.000001" max="1000000" step="0.001" value="${esc(p?.purchase_to_base_quantity??'1')}" required><span class="hint">Quantidade da unidade-base em uma unidade de compra</span></label>${productSelect('Alerta de vencimento','expiry_alert_days',expiryOptions,String(p?.expiry_alert_days??7),'add-expiry-alert')}${productSelect('Fornecedor principal','supplier_id',supplierOptions,p?.supplier_id,'add-supplier-from-product')}<label>Estoque mínimo<input name="minimum_quantity" inputmode="decimal" value="${esc(p?.minimum_quantity??'0')}" required></label><label>Quantidade desejada<input name="target_quantity" inputmode="decimal" value="${esc(p?.target_quantity??p?.minimum_quantity??'0')}" required><span class="hint">Nível que a gestão quer manter</span></label><label>Prazo de entrega (dias)<input name="supplier_lead_days" type="number" min="0" max="365" step="1" value="${esc(p?.supplier_lead_days??'0')}" required></label><div class="form-section-title">Armazenamento e orientações</div><label>Local de armazenamento<input name="storage_location" maxlength="160" value="${esc(p?.storage_location||'')}" placeholder="Ex.: câmara fria · prateleira 2"></label><label>Condições de conservação<input name="storage_conditions" maxlength="300" value="${esc(p?.storage_conditions||'')}" placeholder="Conforme orientação do fabricante"></label><label class="form-span-2">Descrição e observações<textarea name="description" maxlength="2000" rows="3">${esc(p?.description||'')}</textarea></label><div class="form-actions"><button type="submit" class="button primary">${p?'Salvar alterações':'Salvar produto'}</button></div></form>`;}
  async function showProductForm(productId=''){const data=await productModalData(productId);if(productId&&!data.product)throw new Error('Produto não encontrado.');openModal(productId?'Editar produto':'Cadastrar produto',productFormMarkup(data),{className:'catalog-modal'});}
  function supplierFormMarkup(visibility,supplier=null){const optionalFields=supplierFormFieldGroups.map(group=>{const visible=group.fields.filter(field=>visibility[field.key]);if(!visible.length)return '';const section=group.section?`<div class="supplier-form-section">${esc(group.title)}</div>`:'';return `${section}${visible.map(field=>{const className=field.full?' class="form-span-2"':'',value=esc(supplier?.[field.key]||'');if(field.textarea)return `<label${className}>${esc(field.label)}<textarea name="${esc(field.key)}" maxlength="${field.max}" rows="3">${value}</textarea></label>`;const autocomplete=field.autocomplete||(field.type==='email'?'email':field.type==='tel'?'tel':'off');return `<label${className}>${esc(field.label)}<input name="${esc(field.key)}" type="${field.type||'text'}" maxlength="${field.max}" autocomplete="${esc(autocomplete)}" value="${value}"></label>`;}).join('')}`;}).join(''),editing=!!supplier;return `<form id="supplier-form" data-guard-dirty="true" data-edit-id="${esc(supplier?.id||'')}" class="form-grid"><label class="form-span-2">Nome do fornecedor<input name="name" maxlength="160" required autocomplete="organization" value="${esc(supplier?.name||'')}"></label><label class="form-span-2 cnpj-field">CNPJ<input name="cnpj" maxlength="18" inputmode="text" autocomplete="off" placeholder="00.000.000/0000-00" value="${esc(supplier?.cnpj||'')}"><span class="hint">Opcional · ao informar 14 caracteres, os dados disponíveis serão preenchidos automaticamente</span><span class="lookup-status" id="supplier-lookup-status" aria-live="polite"></span></label>${optionalFields}<div class="form-actions"><button type="submit" class="button primary">${editing?'Salvar alterações':'Salvar fornecedor'}</button></div></form>`;}
  async function showSupplierForm(fromProduct=false,returnToForm='',supplier=null){const settings=await api(`/api/settings?unit_id=${state.unit.id}`),visibility=supplierFormFieldVisibility(settings.supplier_form_fields?.value);openModal(supplier?'Editar fornecedor':'Cadastrar fornecedor',supplierFormMarkup(visibility,supplier),{className:'supplier-modal'});const form=$('#supplier-form');form.dataset.returnToForm=returnToForm||(fromProduct?'product-form':'');}
  function lotFormMarkup({product,suppliers,products}){const supplierOptions='<option value="">Sem fornecedor</option>'+suppliers.map(s=>`<option value="${esc(s.id)}" ${product?.supplier_id===s.id?'selected':''}>${esc(s.name)}</option>`).join(''),base=product?.base_unit||'unidade',conversion=Number(product?.purchase_to_base_quantity||1).toLocaleString('pt-BR',{maximumFractionDigits:3}),picker=products?`<label class="form-span-2">Produto<select data-lot-product required><option value="">Selecione o produto</option>${products.map(p=>`<option value="${esc(p.id)}">${esc(p.name)}</option>`).join('')}</select></label>`:'';return `<form id="lot-form" data-product-id="${esc(product?.id||'')}" class="form-grid">${picker}<label>Quantidade de compra<input name="quantity" inputmode="decimal" required></label><label>Unidade de compra<input name="unit" value="${esc(product?.purchase_unit||base)}"></label><label><span data-lot-conversion-label>Conversão para ${esc(base)}</span><input name="conversion" inputmode="decimal" value="${esc(conversion)}" required><span class="hint">Fica registrada neste lote, mesmo se o cadastro do produto mudar.</span></label><label>Data de recebimento<input name="received_on" type="date" value="${today()}" required></label><label>Validade<input name="expires_on" type="date"><span class="hint">Deixe vazio se não houver informação.</span></label><label class="form-span-2">Fornecedor<div class="select-add"><select name="supplier_id">${supplierOptions}</select><button type="button" class="icon-button" data-action="add-supplier-from-lot" aria-label="Adicionar fornecedor">＋</button></div></label><label>Custo da embalagem (R$)<input name="unit_cost" inputmode="decimal" value="0,00"><span class="hint">O custo por <span data-lot-base>${esc(base)}</span> será calculado para comparação.</span></label><label>Lote<input name="lot_code"></label><label class="form-span-2">Nota/documento<input name="source_document"></label><div class="form-actions"><button type="submit" class="button primary">Registrar lote</button></div></form>`;}
  async function showReceiveProductForm(action){const [suppliers,products]=await Promise.all([api(`/api/suppliers?unit_id=${state.unit.id}`),api(`/api/products?unit_id=${state.unit.id}`)]),product=products.find(p=>p.id===action.dataset.id)||{id:action.dataset.id};openModal(`Receber lote · ${esc(action.dataset.name)}`,lotFormMarkup({product,suppliers}));}
  async function showReceiveStockQuick(){const [suppliers,products]=await Promise.all([api(`/api/suppliers?unit_id=${state.unit.id}`),api(`/api/products?unit_id=${state.unit.id}`)]);if(!products.length){toast('Cadastre um produto no Estoque antes de receber.',true);return;}openModal('Receber estoque',lotFormMarkup({product:null,suppliers,products}),{className:'entry-modal'});const form=$('#lot-form'),pick=$('[data-lot-product]',form);pick.addEventListener('change',()=>{const p=products.find(x=>x.id===pick.value);form.dataset.productId=p?.id||'';if(!p)return;const base=p.base_unit||'unidade';form.elements.unit.value=p.purchase_unit||base;form.elements.conversion.value=Number(p.purchase_to_base_quantity||1).toLocaleString('pt-BR',{maximumFractionDigits:3});form.elements.supplier_id.value=p.supplier_id||'';$('[data-lot-conversion-label]',form).textContent=`Conversão para ${base}`;$('[data-lot-base]',form).textContent=base;});}
  async function showCatalogOption(kind){const item=kind==='item_type',title=item?'Adicionar tipo de item':'Adicionar alerta de vencimento',body=item?`<form id="catalog-option-form" data-kind="item_type" data-guard-dirty="true" class="form-grid"><label class="form-span-2">Nome do tipo<input name="label" maxlength="60" required placeholder="Ex.: Hortifruti"></label><div class="form-actions"><button type="submit" class="button primary">Adicionar tipo</button></div></form>`:`<form id="catalog-option-form" data-kind="expiry_alert" data-guard-dirty="true" class="form-grid"><label>Alertar com quantos dias de antecedência?<input name="value" type="number" min="0" max="3650" step="1" required placeholder="Ex.: 10"></label><div class="form-actions"><button type="submit" class="button primary">Adicionar alerta</button></div></form>`;openModal(title,body,{className:'confirm-modal'});}
