  document.addEventListener('click',e=>{if(e.target.id==='logout-button'||e.target.id==='mobile-logout'){post('/api/auth/logout',{}).finally(()=>{state.user=null;state.csrf='';showLogin();});}if(e.target.id==='menu-toggle'){const open=$('#sidebar').classList.toggle('open');e.target.setAttribute('aria-expanded',String(open));}if(e.target.id==='sidebar-collapse'){const collapsed=document.body.classList.toggle('sidebar-collapsed');e.target.setAttribute('aria-expanded',String(!collapsed));e.target.setAttribute('aria-label',collapsed?'Expandir navegação':'Recolher navegação');e.target.title=collapsed?'Expandir navegação':'Recolher navegação';}if($('#sidebar').classList.contains('open')&&!e.target.closest('#sidebar')&&e.target.id!=='menu-toggle'){ $('#sidebar').classList.remove('open');$('#menu-toggle').setAttribute('aria-expanded','false');}});
  async function initializeSession(){try{const me=await api('/api/auth/me');state.user=me.user;state.csrf=me.csrf;if(me.user.mustChangePassword){showPasswordChange();return;}state.units=me.units;state.unit=me.units[0];showApp();const previewMode=document.body.dataset.previewMode==='true',requestedPage=new URLSearchParams(location.search).get('page'),validPages=['overview','sales','inventory','inventory-costs','inventory-waste','suppliers','purchases','attachments','expenses','cash','dre','reports','import','audit','product-audit','users','settings'];setPage(previewMode&&validPages.includes(requestedPage)?requestedPage:'overview');}catch(e){showLogin();}}
